#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"FAIL %d: %s\n",__LINE__,#x);exit(1);}}while(0)
static char *call(const SourcesConfig *cfg,const char *input,int expected){char *out=NULL;size_t n;FILE *stream=open_memstream(&out,&n);CHECK(stream);int rc=sources_dispatch(cfg,input,strlen(input),stream);CHECK(!fclose(stream));if(rc!=expected)fprintf(stderr,"response %s\n",out);CHECK(rc==expected);Json j;CHECK(json_parse(&j,out,n));return out;}
static void file(const char *path,const char *value){FILE *out=fopen(path,"w");CHECK(out);CHECK(fputs(value,out)>=0);CHECK(!fclose(out));}
static char *field(const char *out,const char *key){Json j;CHECK(json_parse(&j,out,strlen(out)));char *value=json_string(&j,json_get(&j,0,key));CHECK(value);return value;}
static char *locator(const char *out){Json j;CHECK(json_parse(&j,out,strlen(out)));char *value=json_string(&j,json_get(&j,json_get(&j,0,"provenance"),"locator"));CHECK(value);return value;}
